from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime, timedelta, timezone
IST=timezone(timedelta(hours=5,minutes=30))
def norm_rider(r):
    m=re.fullmatch(r'\s*[Rr]0*(\d+)\s*',r); return 'R%03d'%int(m.group(1)) if m else r
def norm_dist(d):
    d=float(d); return d/1000 if d>100 else d
def fare(d,s): return int(Decimal(str((25+6*max(0.0,d-2))*s)).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
raw=list(csv.DictReader(open('data/trips.csv'))); seen=set(); trips=[]
for t in raw:
    k=tuple(sorted(t.items()))
    if k in seen: continue
    seen.add(k)
    trips.append({'id':t['trip_id'],'r':norm_rider(t['rider_id']),
      'day':datetime.fromisoformat(t['started_at'].replace('Z','+00:00')).astimezone(IST).date(),
      's':t['status'],'km':norm_dist(t['distance_km']),'x':float(t['surge_multiplier'])})
lines=list(csv.DictReader(open('data/payout_lines.csv')))
paid={l['trip_id']:int(l['amount']) for l in lines if l['line_type']=='trip'}
inc={(l['rider_id'],l['payout_date']) for l in lines if l['line_type']=='daily_incentive'}
pen=collections.Counter(l['trip_id'] for l in lines if l['line_type']=='cancellation_penalty')
byrd=collections.defaultdict(list)
for t in trips: byrd[(t['r'],t['day'])].append(t)

def shortfall_window(rider, received_at):
    anchor=datetime.fromisoformat(received_at).astimezone(IST).date()
    total=0; detail=[]
    for i in range(0,8):
        day=anchor-timedelta(days=i)
        if not (anchor-day).days<=7: continue
        ts=byrd.get((rider,day),[]); comp=[t for t in ts if t['s']=='completed']
        for t in comp:
            owed=fare(t['km'],t['x']); got=paid.get(t['id'])
            if got is None: total+=owed; detail.append((str(day),t['id'],'unpaid',owed))
            elif got<owed: total+=owed-got; detail.append((str(day),t['id'],'short',owed-got))
        if len(comp)>=12 and (rider,str(day)) not in inc: total+=150; detail.append((str(day),'-','incentive',150))
        for t in ts:
            if t['s']=='cancelled_by_rider' and pen.get(t['id'],0)>1:
                e=(pen[t['id']]-1)*10; total+=e; detail.append((str(day),t['id'],'dbl_penalty',e))
    return total, detail

convs=json.load(open('data/conversations.json'))
for i,c in enumerate(convs,1):
    first=[t for t in c['turns'] if t.get('from')=='rider'][0]
    tot,det=shortfall_window(c['rider_id'], first['received_at'])
    exp=c['expected']
    e=exp.get('payout'); a=exp.get('approval')
    tag=f"payout={e} approval={a}" if 'one_of' not in exp else f"one_of={exp['one_of']}"
    print(f"{i:2} {c['rider_id']} win_shortfall={tot:5} | expected {tag} esc={exp.get('escalation')}")
    if tot: print("      ", det)
