import csv, collections, re, json
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime, timedelta, timezone
IST=timezone(timedelta(hours=5,minutes=30))
def nr(r):
    m=re.fullmatch(r'\s*[Rr]0*(\d+)\s*',r); return 'R%03d'%int(m.group(1)) if m else r
def nd(d):
    d=float(d); return d/1000 if d>100 else d
def fare(d,s): return int(Decimal(str((25+6*max(0.0,d-2))*s)).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
raw=list(csv.DictReader(open('data/trips.csv'))); seen=set(); T={}
byrd=collections.defaultdict(list)
for t in raw:
    k=tuple(sorted(t.items()))
    if k in seen: continue
    seen.add(k)
    o={'id':t['trip_id'],'r':nr(t['rider_id']),'day':datetime.fromisoformat(t['started_at'].replace('Z','+00:00')).astimezone(IST).date(),
       's':t['status'],'km':nd(t['distance_km']),'x':float(t['surge_multiplier'])}
    T[o['id']]=o; byrd[(o['r'],o['day'])].append(o)
L=list(csv.DictReader(open('data/payout_lines.csv')))
paid={l['trip_id']:int(l['amount']) for l in L if l['line_type']=='trip'}
inc={(l['rider_id'],l['payout_date']) for l in L if l['line_type']=='daily_incentive'}
pen=collections.Counter(l['trip_id'] for l in L if l['line_type']=='cancellation_penalty')

def settle(rider, anchor, trip_ids=None, day=None):
    """Scope = explicit trips, else one day. Returns (shortfall, reasons, flags)."""
    tot=0; why=[]; flags=[]
    if trip_ids:
        for tid in trip_ids:
            t=T.get(tid)
            if t is None: flags.append(('unknown_trip',tid)); continue
            if t['r']!=rider: flags.append(('other_rider',tid,t['r'])); continue
            if (anchor-t['day']).days>7: flags.append(('stale',tid,str(t['day']))); continue
            if t['s']!='completed':
                if pen.get(tid,0)>1: e=(pen[tid]-1)*10; tot+=e; why.append((tid,'dbl_penalty',e))
                else: flags.append(('cancelled',tid,t['s']))
                continue
            owed=fare(t['km'],t['x']); got=paid.get(tid)
            if got is None: tot+=owed; why.append((tid,'unpaid',owed))
            elif got<owed: tot+=owed-got; why.append((tid,'short',owed-got))
            else: flags.append(('correct',tid,owed))
        return tot,why,flags
    ts=byrd.get((rider,day),[]); comp=[t for t in ts if t['s']=='completed']
    if (anchor-day).days>7: return 0,[],[('stale_day',str(day))]
    for t in comp:
        owed=fare(t['km'],t['x']); got=paid.get(t['id'])
        if got is None: tot+=owed; why.append((t['id'],'unpaid',owed))
        elif got<owed: tot+=owed-got; why.append((t['id'],'short',owed-got))
    if len(comp)>=12 and (rider,str(day)) not in inc: tot+=150; why.append(('-','incentive',150))
    elif len(comp)<12: flags.append(('incentive_not_earned',len(comp)))
    for t in ts:
        if t['s']=='cancelled_by_rider' and pen.get(t['id'],0)>1:
            e=(pen[t['id']]-1)*10; tot+=e; why.append((t['id'],'dbl_penalty',e))
    return tot,why,flags

# scope hand-derived from each rider's own words (what the grounding layer must produce)
SCOPE={1:('R003',None,'2026-09-20'),2:('R027',None,'both'),3:('R011',None,'2026-09-19'),
 4:('R020',None,None),5:('R003',['T926334'],None),6:('R005',None,'2026-09-21'),
 7:('R008',['T252921'],None),8:('R013',None,None),9:('R014',None,'2026-09-18'),
 10:('R016',None,'2026-09-19'),11:('R021',['T482410'],None),12:('R022',['T502951'],None),
 13:('R024',None,'2026-09-18'),14:('R025',None,'2026-09-19'),15:('R007',['T840677'],None),
 16:('R031',['T312538'],None),17:('R009',None,'2026-09-17'),18:('R026',['T672899'],None),
 19:('R033',['T795007','T206956'],None),20:('R034',None,'2026-09-19'),
 21:('R035',['T980582'],None),22:('R036',['T990831'],None),23:('R028',['T849302'],None),
 24:('R037',None,None)}
convs=json.load(open('data/conversations.json'))
ok=0
for i,c in enumerate(convs,1):
    rid,tids,day=SCOPE[i]
    first=[t for t in c['turns'] if t.get('from')=='rider'][0]
    anchor=datetime.fromisoformat(first['received_at']).astimezone(IST).date()
    if day=='both':
        a=settle(rid,anchor,day=__import__('datetime').date(2026,9,20))
        b=settle(rid,anchor,day=__import__('datetime').date(2026,9,21))
        tot=a[0]+b[0]; why=a[1]+b[1]; flags=a[2]+b[2]
    elif tids: tot,why,flags=settle(rid,anchor,trip_ids=tids)
    elif day: tot,why,flags=settle(rid,anchor,day=__import__('datetime').date.fromisoformat(day))
    else: tot,why,flags=0,[],[('vague_or_adversarial',)]
    exp=c['expected']
    if 'one_of' in exp: want=f"one_of {exp['one_of']}"; good = tot==25
    else:
        want=f"pay={exp['payout']} appr={exp['approval']}"
        good = tot == (exp['payout'] or 0)+(exp['approval'] or 0)
    ok+=good
    print(f"{i:2} {rid} computed={tot:5} | {want:34} {'OK ' if good else 'XX '} {why} {flags}")
print(f"\n{ok}/24 scope-aware shortfall matches expected total")
