        total, ids = 0, set()
        for payout in self.ledger(rider_id):
            payout_id = str(payout.get("payout_id", ""))
            if payout_id in ids:
                continue
            ids.add(payout_id)
            try:
                total += int(payout.get("amount", 0))
            except (TypeError, ValueError):
                pass
        return total, ids


