        "rider_id": rider_id,
        "scenario": case.get("scenario", ""),
        "paid": paid,
        "payouts": new_payouts,
        "approvals": approvals,
        "escalations": len(escalations),
        "expected": expected,
        "failures": failures,
        "passed": not failures,
        "replies": replies,
        "slowest_ms": int(slowest * 1000),
    }


