import pathlib
p = pathlib.Path("app/llm.py"); s = p.read_text()

old = '''# The schema the provider is constrained to. Note what is absent: there is no
# field for an amount to pay. The model cannot express a payment.
CLAIM_SCHEMA = {
    "type": "object",
    "properties": {
        "claims": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "kind": {"type": "string", "enum": CLAIM_KINDS},
                    "trip_ids": {"type": "array", "items": {"type": "string"}},
                    "date_hint": {"type": "string"},
                    "amount_claimed": {"type": "integer"},
                    "confidence": {"type": "number"},
                },
                "required": ["kind"],
                "additionalProperties": False,
            },
        }
    },
    "required": ["claims"],
    "additionalProperties": False,
}'''

new = '''# The schema the provider is constrained to. Note what is absent: there is no
# field for an amount to pay. The model cannot express a payment.
#
# Strict mode (OpenAI-compatible, which is what Groq serves) requires every
# property to appear in `required`, so genuinely optional fields are declared
# nullable rather than omitted. Getting this wrong is a 400, not a silent
# degradation -- the provider refuses the request outright.
CLAIM_SCHEMA = {
    "type": "object",
    "properties": {
        "claims": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "kind": {"type": "string", "enum": CLAIM_KINDS},
                    "trip_ids": {"type": "array", "items": {"type": "string"}},
                    "date_hint": {"type": ["string", "null"]},
                    "amount_claimed": {"type": ["integer", "null"]},
                    "confidence": {"type": "number"},
                },
                "required": [
                    "kind",
                    "trip_ids",
                    "date_hint",
                    "amount_claimed",
                    "confidence",
                ],
                "additionalProperties": False,
            },
        }
    },
    "required": ["claims"],
    "additionalProperties": False,
}'''
assert old in s
s = s.replace(old, new)

old_g = '''def _gemini_schema(schema: dict) -> dict:
    """Gemini's response_schema is a subset of JSON Schema: it rejects
    additionalProperties and wants uppercase types."""
    if not isinstance(schema, dict):
        return schema
    out: dict = {}
    for key, value in schema.items():
        if key == "additionalProperties":
            continue
        if key == "type" and isinstance(value, str):
            out["type"] = value.upper()
        elif key == "properties":
            out["properties"] = {k: _gemini_schema(v) for k, v in value.items()}
        elif key == "items":
            out["items"] = _gemini_schema(value)
        else:
            out[key] = value
    return out'''

new_g = '''def _gemini_schema(schema: dict) -> dict:
    """Translate the strict JSON Schema above into Gemini's dialect.

    Gemini takes a subset: it rejects additionalProperties, wants uppercase type
    names, and expresses optionality as `nullable` rather than a type union --
    so the ["string", "null"] unions strict mode forced on us have to be
    unpacked again here.
    """
    if not isinstance(schema, dict):
        return schema
    out: dict = {}
    for key, value in schema.items():
        if key == "additionalProperties":
            continue
        if key == "type":
            if isinstance(value, list):
                concrete = [t for t in value if t != "null"]
                out["type"] = (concrete[0] if concrete else "string").upper()
                if "null" in value:
                    out["nullable"] = True
            else:
                out["type"] = value.upper()
        elif key == "properties":
            out["properties"] = {k: _gemini_schema(v) for k, v in value.items()}
        elif key == "items":
            out["items"] = _gemini_schema(value)
        else:
            out[key] = value
    return out'''
assert old_g in s
s = s.replace(old_g, new_g)

s = s.replace(
'GROQ_MODEL = os.getenv("GROQ_MODEL", "llama-3.3-70b-versatile")',
'# Groq retired the llama-3.3 ids; gpt-oss-120b is what this account can reach.\nGROQ_MODEL = os.getenv("GROQ_MODEL", "openai/gpt-oss-120b")')
p.write_text(s)
print("patched app/llm.py")

for f in (".env", ".env.example"):
    q = pathlib.Path(f)
    if q.exists():
        t = q.read_text()
        t = t.replace("GROQ_MODEL=llama-3.3-70b-versatile", "GROQ_MODEL=openai/gpt-oss-120b")
        q.write_text(t)
        print("updated", f)

q = pathlib.Path("docker-compose.yml"); t = q.read_text()
t = t.replace("${GROQ_MODEL:-llama-3.3-70b-versatile}", "${GROQ_MODEL:-openai/gpt-oss-120b}")
q.write_text(t)
print("updated docker-compose.yml")
PY
